items = json.loads(SRC)

# ---------- 枚举硬守卫（§3.114a） ----------
_bad = [(i + 1, x.get('track'), x.get('category'), x.get('direction'))
        for i, x in enumerate(items)
        if {x.get('track')} - VALID_TRACK or {x.get('category')} - VALID_CAT or {x.get('direction')} - VALID_DIR]
if _bad:
    raise SystemExit(f'⚠️ §3.114a 非法枚举：{_bad}')

# ---------- §3.129d：标题前 24 字唯一性守卫（规则表键碰撞前置拦截） ----------
_pref = [x['title'][:24] for x in items]
_dup = [p for p in set(_pref) if _pref.count(p) > 1]
if _dup:
    raise SystemExit(f"⚠️ §3.129d 标题前 24 字碰撞：{_dup}")

# ---------- 逐条补齐字段 ----------
for i, x in enumerate(items, 1):
    x['idx'] = i
    x['window'] = WIN
    x.setdefault('source_url', '')
    if not x.get('source_url'):
        print(f"  ⚠️ 第 {i} 条无 source_url（按约定留空）")

# ---------- [§3.144a 硬守卫] QDII notional 必须取本日 tracks[].mv，禁止用 detail[].mv ----------
_PC = json.load(open(os.path.join(BASE, 'data/processed/history/portfolio_close_20261014.json'), encoding='utf-8'))
QDII_MV_TRACK = _PC['tracks']['美股标普医药']['mv']
QDII_MV_DETAIL = round(sum(float(r['mv']) for r in _PC['detail'] if r['track'] == '美股标普医药'), 2)
assert abs(QDII_MV_TRACK - QDII_MV_DETAIL) > 1.5, \
    '[§3.144a] 守卫失效：tracks[].mv 与 detail[].mv 恰好相等，守卫无法区分两者，须人工确认'
QDII_MV_DECLARED = 58690.46
assert abs(QDII_MV_DECLARED - QDII_MV_TRACK) < 1.5, (
    f'[§3.144a 硬守卫] 正文声明的 QDII notional {QDII_MV_DECLARED:,.2f} 元 != '
    f'tracks["美股标普医药"].mv {QDII_MV_TRACK:,.2f} 元（detail[].mv = {QDII_MV_DETAIL:,.2f} 元，为陈旧继承值）-> 终止')
print(f'[§3.144a] 守卫通过：QDII notional = {QDII_MV_TRACK:,.2f} 元（tracks[].mv）；detail[].mv = {QDII_MV_DETAIL:,.2f} 元（已排除）')

json.dump(items, open(OUT, 'w', encoding='utf-8'), ensure_ascii=False, indent=1)
